// Ledgerlight office hours (Eastern). Mon=1 ... Sat=6. Sunday closed.
const ZONE = 'America/New_York';
const HOURS = { 1: [9, 17], 2: [9, 17], 3: [9, 17], 4: [9, 17], 5: [9, 17], 6: [9, 13] };
const STEP = 30;        // minutes between possible start times
const MAX_SLOTS = 3;    // how many options to return

const body = $('Webhook').first().json.body || {};
const duration = Number(body.duration_minutes) || 60;
const day = DateTime.fromISO(body.date || '', { zone: ZONE });

if (!day.isValid) {
  return [{ json: { available: false, message: 'I need a specific date to check. What day works for you?', slots: [] } }];
}

const hours = HOURS[day.weekday];
if (!hours) {
  return [{ json: { available: false, message: `We're closed on ${day.toFormat('cccc')}s.`, slots: [] } }];
}

// Existing events from Google Calendar (all-day events block the whole day)
const busy = $input.all()
  .map(i => i.json)
  .filter(e => e.start)
  .map(e => ({
    start: DateTime.fromISO(e.start.dateTime || e.start.date, { zone: ZONE }),
    end: DateTime.fromISO(e.end.dateTime || e.end.date, { zone: ZONE }),
  }));

const now = DateTime.now().setZone(ZONE);
const close = day.set({ hour: hours[1], minute: 0, second: 0, millisecond: 0 });
let cursor = day.set({ hour: hours[0], minute: 0, second: 0, millisecond: 0 });
const slots = [];

while (cursor.plus({ minutes: duration }) <= close && slots.length < MAX_SLOTS) {
  const end = cursor.plus({ minutes: duration });
  const clash = busy.some(b => cursor < b.end && end > b.start);
  if (!clash && cursor > now) {
    slots.push({
      start: cursor.toISO(),
      spoken: cursor.toFormat("cccc, LLLL d 'at' h:mm a"),
    });
  }
  cursor = cursor.plus({ minutes: STEP });
}

return [{ json: {
  available: slots.length > 0,
  message: slots.length
    ? 'Open times found.'
    : `Nothing is open on ${day.toFormat('cccc, LLLL d')}. Would another day work?`,
  slots,
} }];
